const html="<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>FYP · Lecturer QR Attendance</title>
<style>
:root{font-family:system-ui,-apple-system,Segoe UI,Arial;background:#f6f7fb;color:#171e2c}*{box-sizing:border-box}
body{margin:0}.wrap{max-width:920px;margin:auto;padding:22px}.brand{background:#b8192f;color:#fff;padding:19px 22px;border-radius:0 0 15px 15px}.brand h1{margin:0;font-size:24px}.brand small{opacity:.86}h2{font-size:18px}label{font-size:12px;font-weight:750;display:block;margin-bottom:7px}
input{width:100%;border:1px solid #ccd1da;border-radius:10px;padding:14px;font-size:15px}button{cursor:pointer;border:0;border-radius:10px;padding:13px 15px;font-size:14px;font-weight:750;background:#b8192f;color:#fff}button.secondary{background:#18263e}button:disabled{opacity:.45;cursor:not-allowed}
.card{background:white;border:1px solid #e2e5ec;border-radius:13px;padding:22px;margin:16px 0;box-shadow:0 3px 15px #1b27400b}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}.msg{font-size:13px;line-height:1.5;color:#485469}.success{color:#077748}.error{color:#b8192f}.qr{min-height:350px;display:flex;align-items:center;justify-content:center;background:#fff;border:2px dashed #cfd4e0;border-radius:15px;padding:18px}.qr img{max-width:100%}.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.stat{font-size:23px;font-weight:850;color:#b8192f}.hidden{display:none}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;word-break:break-word;font-size:12px}@media(max-width:700px){.form,.split{grid-template-columns:1fr}.brand h1{font-size:20px}}</style></head>
<body><div class="wrap"><header class="brand"><h1>Smart Academic Attendance · Lecturer QR</h1><small>Course 2244 · Microsoft-authenticated student scan → Qwickly proxy</small></header>
<div class="card"><h2>1 · Lecturer access</h2><div class="form"><div><label for="pin">Lecturer PIN (configured in n8n)</label><input id="pin" type="password" autocomplete="off" placeholder="Enter your private lecturer PIN"/></div><div><label for="title">Class title</label><input id="title" maxlength="200" value="FYP Attendance - Live Class"/></div></div><div class="actions"><button id="start" onclick="startClass()">Create Qwickly session</button><button class="secondary" onclick="resumeClass()">Reconnect to existing session</button><button class="secondary" onclick="stopClass()">End class</button></div><p id="status" class="msg">Enter PIN, then create a fresh class session. Use a TEST student for the first live POST.</p></div>
<div class="split"><div class="card"><h2>2 · Scan this QR using the Expo app</h2><div id="qr" class="qr"><span class="msg">Start a Qwickly session to generate a QR.</span></div></div><div class="card"><h2>Live class status</h2><p class="msg">Session</p><div id="session" class="stat">Not started</div><p class="msg">QR expires in</p><div id="countdown" class="stat">—</div><p class="msg">QR automatically refreshes. Students must be signed in with their university Microsoft account. Each student gets one attendance record for the session; multiple students may scan the same displayed QR.</p><p id="debug" class="mono"></p></div></div></div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>
const API='https://fyp-workflow.swin.click/webhook/fyp/qr/manage';let active=false,expiresAt=0,previous='',polling=false;
const el=id=>document.getElementById(id);
function status(msg,bad=false){el('status').textContent=msg;el('status').className='msg '+(bad?'error':'success')}
async function manage(action){const pin=el('pin').value.trim();if(!pin)throw Error('Enter the lecturer PIN first.');const body=new URLSearchParams({lecturerKey:pin,action,title:el('title').value.trim()||'Class Attendance'});let res;try{res=await fetch(API,{method:'POST',body,cache:'no-store'})}catch(e){throw Error('Cannot reach n8n. Verify workflow ACTIVE and CORS settings. '+e.message)}let data;try{data=await res.json()}catch{throw Error('n8n did not return JSON (HTTP '+res.status+').')}if(!res.ok||!data.ok)throw Error(data.message||('HTTP '+res.status));return data;}
async function startClass(){el('start').disabled=true;try{const d=await manage('start');active=true;el('session').textContent='#'+d.sessionId;status('Qwickly session '+d.sessionId+' created. Display QR for students.');await issue()}catch(e){status(e.message,true)}finally{el('start').disabled=false}}
async function resumeClass(){try{active=true;await issue();status('Reconnected. Display the QR for students.')}catch(e){active=false;status(e.message,true)}}
async function stopClass(){try{let d=await manage('stop');active=false;expiresAt=0;previous='';el('qr').innerHTML='<span class="msg">Class ended.</span>';el('session').textContent='Closed';el('countdown').textContent='—';status(d.message||'Class closed.')}catch(e){status(e.message,true)}}
async function issue(){if(!active||polling)return;polling=true;try{let d=await manage('issue');if(!d.qrData)throw Error('n8n did not return a QR payload.');expiresAt=d.expiresAt;el('session').textContent='#'+d.sessionId;el('debug').textContent='Course 2244 · QR format FYP_ATTENDANCE_DEMO v1';if(d.qrData!==previous){previous=d.qrData;el('qr').innerHTML='';if(typeof QRCode==='undefined')throw Error('QR rendering library unavailable. Check CDN access.');new QRCode(el('qr'),{text:d.qrData,width:300,height:300,colorDark:'#141923',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}}catch(e){status(e.message,true)}finally{polling=false}}
setInterval(()=>{if(!active)return;let secs=Math.max(0,Math.ceil((expiresAt-Date.now())/1000));el('countdown').textContent=secs+' s';if(secs<9)void issue();},1000);
</script></body></html>"; return [{json:{html}}];

const LECTURER_PIN = 'FYPCSS301';

const r = $input.first().json || {};
const b = (r.body && typeof r.body === 'object') ? r.body : {};

const action = String(b.action || '').trim().toLowerCase();
const supplied = String(b.lecturerKey || '');

// Only block if the PIN is empty or still the template placeholder
if (!LECTURER_PIN || LECTURER_PIN === 'CHANGE_ME') {
  return [{
    json: {
      allowed: 'no',
      httpStatus: 503,
      response: {
        ok: false,
        message: 'Configure the lecturer PIN in node 11.'
      }
    }
  }];
}

if (!supplied || supplied !== LECTURER_PIN) {
  return [{
    json: {
      allowed: 'no',
      httpStatus: 401,
      response: {
        ok: false,
        message: 'Lecturer PIN incorrect.'
      }
    }
  }];
}

if (!['start', 'issue', 'stop'].includes(action)) {
  return [{
    json: {
      allowed: 'no',
      httpStatus: 400,
      response: {
        ok: false,
        message: 'Invalid class management action.'
      }
    }
  }];
}

return [{
  json: {
    allowed: 'yes',
    action,
    title: String(b.title || 'Class Attendance')
      .slice(0, 200)
      .trim() || 'Class Attendance'
  }
}];

const r=$input.first().json||{};
function parsed(x){if(x==null)return {};if(typeof x==='string'){try{return JSON.parse(x)}catch{return {raw:x}}}return x}
const raw=parsed(r.body??r.data??r);
const obj=typeof raw==='object'&&raw?raw:{};
const status=Number(r.statusCode??r.status??0);
const id=obj.session_id;
if(status!==201||!/^[0-9]+$/.test(String(id??''))){
 return [{json:{httpStatus:status>=400&&status<600?status:502,response:{ok:false,message:'Qwickly session was not confirmed. Check the proxy key, response and upstream status.',proxyStatus:status,upstreamError:String(obj.error||obj.message||obj.raw||'').slice(0,400)}}}];
}
const s=$getWorkflowStaticData('global');
s.qrAttendance={sessionId:String(id),courseLmsId:'2244',title:String(obj.title||$('11 · SET LECTURER PIN · Authorize').first().json.title),startedAt:Date.now(),active:true,proof:null,previousProof:null,expiresAt:0,previousValidUntil:0};
return [{json:{httpStatus:201,response:{ok:true,sessionId:String(id),courseLmsId:'2244',message:'Qwickly session created and stored. Lecturer can now issue QR.'}}}];

const s=$getWorkflowStaticData('global');const x=s.qrAttendance;
if(!x||!x.active)return [{json:{httpStatus:409,response:{ok:false,message:'No active session. Create a new Qwickly session first.'}}}];
const now=Date.now();
if(!x.proof||now>=Number(x.expiresAt||0)){
  x.previousProof=x.proof||null; x.previousValidUntil=now+8000;
  // Long random challenge, validated only server-side. QR contains no proxy secret.
  x.proof=Array.from({length:5},()=>Math.random().toString(36).slice(2).padEnd(10,'0')).join('')+String(now);
  x.expiresAt=now+45000;
}
const qrData=JSON.stringify({type:'FYP_ATTENDANCE_DEMO',v:1,courseLmsId:'2244',sessionId:String(x.sessionId),proof:x.proof});
return [{json:{httpStatus:200,response:{ok:true,courseLmsId:'2244',sessionId:String(x.sessionId),title:x.title,qrData,expiresAt:x.expiresAt,message:'Active QR'}}}];

const s=$getWorkflowStaticData('global');const x=s.qrAttendance;
if(x){x.active=false;x.proof=null;x.previousProof=null;x.expiresAt=0;}
return [{json:{httpStatus:200,response:{ok:true,message:'QR scanning disabled for this class. Qwickly records remain intact.',sessionId:x?.sessionId||null}}}];

const r=$input.first().json||{};const b=(r.body&&typeof r.body==='object')?r.body:{};
const h=r.headers||{};const a=String(h.authorization||h.Authorization||'');
const reject=(status,msg)=>[{json:{allowed:'no',httpStatus:status,response:{ok:false,demo:false,recordedInQwickly:false,status:'rejected',message:msg}}}];
if(!/^Bearer\s+\S+$/i.test(a))return reject(401,'Microsoft Graph bearer token missing. Sign in again.');
if(!/^\d{6,12}$/.test(String(b.sisId||'')))return reject(400,'Valid signed-in student SIS ID required.');
if(typeof b.qrData!=='string'||b.qrData.length>4096)return reject(400,'Invalid or oversized QR payload.');
let q;try{q=JSON.parse(b.qrData)}catch{return reject(400,'QR must contain valid JSON.');}
const s=$getWorkflowStaticData('global');const x=s.qrAttendance;
if(!x||x.active!==true)return reject(410,'No active class session. Ask lecturer to start one.');
if(!q||q.type!=='FYP_ATTENDANCE_DEMO'||q.v!==1||q.courseLmsId!=='2244'||String(q.sessionId)!==String(x.sessionId))return reject(400,'QR is not for the active class.');
const now=Date.now();const good=(q.proof===x.proof&&now<=Number(x.expiresAt||0))||(q.proof===x.previousProof&&now<=Number(x.previousValidUntil||0));
if(typeof q.proof!=='string'||!good)return reject(410,'QR expired or invalid. Scan the latest lecturer QR.');
return [{json:{allowed:'yes',accessToken:a.replace(/^Bearer\s+/i,''),claimedSisId:String(b.sisId),sessionId:String(x.sessionId),courseLmsId:'2244'}}];

// IMPORTANT: If the proxy cannot resolve SIS IDs, enter owner-provided Qwickly IDs here.
// Example: const QWICKLY_USER_ID_BY_SIS = {'YOUR_TEST_SIS_ID':'YOUR_QWICKLY_USER_ID'};
const QWICKLY_USER_ID_BY_SIS = {};
const r=$input.first().json||{};
function parsed(x){if(typeof x==='string'){try{return JSON.parse(x)}catch{return {raw:x}}}return x||{}}
const p=parsed(r.body??r.data??r);const status=Number(r.statusCode??r.status??0);
const reject=(code,msg)=>[{json:{allowed:'no',httpStatus:code,response:{ok:false,demo:false,recordedInQwickly:false,status:'identity_rejected',message:msg}}}];
if(status!==200||typeof p!=='object'||!p)return reject(401,'Microsoft identity could not be verified with Graph /me (HTTP '+status+').');
const claim=$('21 · Validate active QR and bearer token').first().json;
const addresses=[p.mail,p.userPrincipalName].filter(x=>typeof x==='string').map(x=>x.trim().toLowerCase());
const matched=addresses.find(v=>/^\d{6,12}@students\.swinburne\.edu\.my$/.test(v));
if(!matched)return reject(403,'Graph user is not a recognized Swinburne student email account.');
const verifiedSisId=matched.split('@')[0];
if(verifiedSisId!==claim.claimedSisId)return reject(403,'Signed-in Microsoft student does not match the requested SIS ID.');
const mapped=QWICKLY_USER_ID_BY_SIS[verifiedSisId];
return [{json:{allowed:'yes',sessionId:claim.sessionId,studentSisId:verifiedSisId,user_identifier:mapped?'id':'sis_id',user_value:mapped?String(mapped):verifiedSisId}}];

const r=$input.first().json||{};
function parsed(x){if(typeof x==='string'){try{return JSON.parse(x)}catch{return {raw:x}}}return x||{}}
const p=parsed(r.body??r.data??r);const code=Number(r.statusCode??r.status??0);
const input=$('24 · VERIFY MICROSOFT STUDENT · MAP Qwickly ID').first().json;
const rawRecord=(p&&typeof p==='object')?(p.record&&typeof p.record==='object'?p.record:p):{};
const rec={id:Number(rawRecord.id),parent_session:Number(rawRecord.parent_session),user_id:Number(rawRecord.user_id),status_id:Number(rawRecord.status_id)};
const confirmed=code===201&&Number.isSafeInteger(rec.id)&&rec.id>0&&rec.parent_session===Number(input.sessionId)&&Number.isSafeInteger(rec.user_id)&&rec.user_id>0&&rec.status_id===286;
if(confirmed){return [{json:{httpStatus:201,response:{ok:true,status:'qwickly_recorded',message:'Attendance recorded successfully in Qwickly.',demo:false,recordedInQwickly:true,courseCode:'2244',sessionId:input.sessionId,record:rec}}}];}
const already=code===409;
const msg=already?'Attendance already exists in Qwickly for this student and session.':code===404?'Qwickly could not find this session or student. Configure the official Qwickly user ID if SIS ID lookup is unsupported.':code===401||code===403?'Qwickly proxy rejected its credential. Check X-Proxy-Key.':'Qwickly attendance POST was not confirmed.';
return [{json:{httpStatus:code>=400&&code<600?code:502,response:{ok:false,status:already?'already_exists':'qwickly_rejected',message:msg,demo:false,recordedInQwickly:false,courseCode:'2244',sessionId:input.sessionId,proxyStatus:code,upstreamError:String(p.error||p.message||p.raw||'').slice(0,400)}}}];
